   "title_nl": "Vaatwerk",
   "page_start": 19,
   "body_ar": "<p>الآنية هي الأوعية التي يحفظ فيها الماء وغيره، ويجوز استعمال الثمين منها غير الذهب والفضة. ويحرم استعمال آنية الذهب والفضة في الأكل والشرب والطهارة وسائر الاستعمال للرجال والنساء، لقوله ﷺ: <span class=\"hadith\">لا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافها فإنها لهم في الدنيا ولنا في الآخرة</span> متفق عليه، و<span class=\"hadith\">الذي يشرب في إناء الفضة إنما يجرجر في بطنه نار جهنم</span> متفق عليه. والمضبب بالذهب حرام مطلقًا، ويجوز اليسير من الفضة للحاجة، لأن قدحه ﷺ انكسر فاتخذ مكان الشعب سلسلة من فضة. وتصح الطهارة من إناء الذهب والفضة على الراجح. وآنية الكفار مباحة إن لم يعرف عنهم مباشرة النجاسة، وإلا فالأولى التنزه عنها، فإن لم يجد غيرها غسلها، لقوله ﷺ: <span class=\"hadith\">إن وجدتم غيرها فلا تأكلوا فيها، وإن لم تجدوا فاغسلوها وكلوا فيها</span> متفق عليه.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 4، من ص 19. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Vaatwerk</strong> (āniya) zijn de bakken waarin water en andere dingen worden bewaard. Kostbaar vaatwerk dat niet van goud of zilver is, zoals van robijn of diamant, is toegestaan, omdat er geen verbod over is overgeleverd.</p>\n<p><strong>Goud en zilver.</strong> Eten, drinken, je reinigen en elk ander gebruik uit vaatwerk van goud of zilver is verboden, voor mannen en vrouwen: <span class=\"hadith\">Drink niet uit vaatwerk van goud en zilver en eet niet uit hun schalen; die zijn voor hen in deze wereld en voor ons in het Hiernamaals</span> (al-Bukhārī en Muslim, van Ḥudhayfa), en <span class=\"hadith\">Wie uit zilveren vaatwerk drinkt, laat het vuur van de Hel in zijn buik klokken</span> (al-Bukhārī en Muslim, van Umm Salama). Dat geldt ook voor lepels, messen, borden en glazen.</p>\n<p><strong>Gerepareerd vaatwerk.</strong> Een reparatie met goud is altijd verboden. Een kleine reparatie met zilver uit noodzaak mag: de beker van de Profeet ﷺ brak en werd met een zilveren draad hersteld (al-Bukhārī, van Anas). Woeḍoe uit een gouden of zilveren bak is volgens de sterkere mening geldig, al is het gebruik zondig, want de bak is geen voorwaarde voor de woeḍoe.</p>\n<p><strong>Vaatwerk van niet-moslims</strong> (ter kennisname). Van wie niet bekend is dat zij met najāsa eten, is het vaatwerk toegestaan; de metgezellen gebruikten het (Aḥmad en Abū Dāwūd, van Jābir). Van wie bekend is dat zij er varkensvlees of wijn in doen, gebruik je het liever niet; heb je niets anders, was het dan eerst: <span class=\"hadith\">Als jullie iets anders vinden, eet er dan niet uit; vinden jullie niets, was ze dan en eet eruit</span> (al-Bukhārī en Muslim, van Abū Thaʿlaba al-Khushanī).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Elk vaatwerk is toegestaan, behalve van goud en zilver.</li>\n<li>Het verbod op goud en zilver geldt voor mannen en vrouwen en voor elk gebruik.</li>\n<li>Een kleine zilveren reparatie uit noodzaak mag; een gouden niet.</li>\n<li>Woeḍoe uit zo'n bak is volgens het boek wel geldig.</li>\n<li>Vaatwerk van niet-moslims die met najāsa eten, was je eerst als je niets anders hebt.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 4, vanaf p. 19. Status: concept, wacht op controle.</p>",
