   "title_ar": "قضاء الحاجة وآدابها",
   "title_nl": "Je behoefte doen en de etiquette",
   "page_start": 25,
   "body_ar": "<p>الاستنجاء إزالة الخارج من السبيلين بالماء، والاستجمار إزالته بالحجارة ونحوها، ويسن أن يكون وترًا: <span class=\"hadith\">من استجمر فليوتر</span> متفق عليه. ومن آداب قضاء الحاجة: التسمية والاستعاذة عند الدخول، وقول <span class=\"hadith\">غفرانك</span> عند الخروج، وتقديم اليسرى دخولًا واليمنى خروجًا، والاستنجاء باليسرى: <span class=\"hadith\">إذا بال أحدكم فلا يمس ذكره بيمينه</span> متفق عليه، وستر العورة. ويحرم التخلي في طريق الناس وظلهم وموارد مياههم: <span class=\"hadith\">اتقوا اللعانين</span> رواه مسلم، واستقبال القبلة واستدبارها في الفضاء دون البنيان. ويكره استقبال مهب الريح، والكلام، والبول في الشق، ودخول الخلاء بما فيه ذكر الله إلا لحاجة، ويحرم الدخول بالمصحف.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 5، من ص 25. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Istinjāʾ en istijmār.</strong> Istinjāʾ is het verwijderen van wat uit de voor- of achterkant kwam met water. Istijmār is dat doen met stenen, papier, stof of tissues. Het is soenna dit een oneven aantal keer te doen: <span class=\"hadith\">Wie zich met stenen reinigt, laat hij het oneven doen</span> (al-Bukhārī en Muslim). Is er geen water, dan is istijmār verplicht.</p>\n<p><strong>Etiquette.</strong> (1) Bij binnengaan zeg je <span class=\"hadith\">Bismillāh</span> en <span class=\"hadith\">Allāhumma innī aʿūdhu bika mina l-khubthi wa l-khabāʾith</span> (at-Tirmidhī; al-Bukhārī en Muslim van Anas). (2) Bij naar buiten gaan: <span class=\"hadith\">Ghufrānak</span> (at-Tirmidhī, van ʿĀʾisha). (3) Links binnen, rechts naar buiten. (4) De linkerhand gebruiken: <span class=\"hadith\">Raak je geslachtsdeel niet met je rechterhand aan</span> (al-Bukhārī en Muslim). (5) Je bedekken voor anderen. Zittend plassen heeft de voorkeur; staand mag als je je niet bevuilt en niet bloot raakt.</p>\n<p><strong>Verboden</strong> (ter kennisname): je behoefte doen op de weg, in de schaduw waar mensen zitten, in parken, onder vruchtbomen en bij waterbronnen: <span class=\"hadith\">Pas op voor de twee dingen die vervloeking brengen</span> (Muslim). In de open vlakte mag je niet met je gezicht of rug naar de Qibla zitten (al-Bukhārī en Muslim, van Abū Ayyūb); in een gebouw of met een afscherming wel (Muslim, van Ibn ʿUmar). Beter is het ook dan te vermijden.</p>\n<p><strong>Afgeraden.</strong> Met de wind mee plassen; praten tijdens het behoefte doen; in een gat plassen; een toilet in gaan met iets waarop Allah's naam staat, behalve bij noodzaak. Een muṣḥaf mag je volgens het boek nooit mee naar binnen nemen. Een telefoon met Koranopnames mag mee, zolang er geen verzen op het scherm staan.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Reinigen kan met water (istinjāʾ) of met stenen en papier (istijmār).</li>\n<li>Bij binnengaan smeek je om bescherming, bij naar buiten gaan om vergeving.</li>\n<li>Gebruik de linkerhand en bedek je.</li>\n<li>Hinder mensen niet met je behoefte op wegen, in schaduw of bij water.</li>\n<li>Neem geen muṣḥaf mee het toilet in.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 5, vanaf p. 25. Status: concept, wacht op controle.</p>",
