   "title_ar": "سنن الفطرة",
   "title_nl": "Gewoonten van de fiṭra",
   "page_start": 30,
   "body_ar": "<p>سنن الفطرة خصال من فعلها اتصف بالفطرة التي فطر الله الناس عليها، منها: السواك، وهو مسنون في كل وقت: <span class=\"hadith\">السواك مطهرة للفم مرضاة للرب</span> رواه النسائي وصححه الألباني، <span class=\"hadith\">لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة</span> رواه مسلم، ويتأكد عند الوضوء والانتباه من النوم وتغير الفم والقراءة والصلاة ودخول المسجد والمنزل؛ وحلق العانة؛ وقص الشارب؛ وإعفاء اللحية؛ وتقليم الأظفار؛ ونتف الإبط؛ وغسل البراجم؛ والختان، وهو واجب في حق الذكر مكرمة في حق الأنثى. ويكره تركها فوق أربعين يومًا.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 6، من ص 30. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Sunan al-fiṭra</strong> zijn gewoonten die passen bij de natuurlijke aanleg waarmee Allah de mensen schiep.</p>\n<p>(1) <strong>De siwāk</strong>, het poetsen van de tanden met een takje of iets dergelijks, is op elk moment soenna: <span class=\"hadith\">De siwāk reinigt de mond en behaagt de Heer</span> (an-Nasāʾī, ṣaḥīḥ volgens al-Albānī) en <span class=\"hadith\">Als het niet zwaar zou zijn voor mijn gemeenschap, had ik hun de siwāk bij elk gebed opgedragen</span> (Muslim). Hij is extra aanbevolen bij woeḍoe, na het slapen, bij een vieze mondgeur, bij Koranrecitatie, gebed en het binnengaan van moskee en huis.</p>\n<p>(2) <strong>Schaamhaar verwijderen</strong>, met scheren of een ander middel.</p>\n<p>(3) <strong>De snor kort houden.</strong></p>\n<p>(4) <strong>De baard laten staan</strong>; volgens het boek is dat in authentieke hadith verplicht.</p>\n<p>(5) <strong>Nagels knippen.</strong></p>\n<p>(6) <strong>Okselhaar verwijderen.</strong></p>\n<p>(7) <strong>De knokkels wassen.</strong></p>\n<p>(8) <strong>Besnijdenis</strong>: verplicht voor mannen, een eervolle daad voor vrouwen, volgens het boek.</p>\n<p>Ter kennisname: deze dingen langer dan veertig dagen laten is afgeraden (Muslim, van Anas). Bekende overleveringen: <span class=\"hadith\">Vijf dingen horen bij de fiṭra</span> (al-Bukhārī en Muslim) en <span class=\"hadith\">Tien dingen horen bij de fiṭra</span> (Muslim, van ʿĀʾisha).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>De siwāk is altijd soenna en extra aanbevolen bij woeḍoe, gebed en Koran.</li>\n<li>Bij de fiṭra horen ook snor, baard, nagels, oksel- en schaamhaar.</li>\n<li>Laat deze dingen niet langer dan veertig dagen gaan.</li>\n<li>Besnijdenis is volgens het boek verplicht voor mannen.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 6, vanaf p. 30. Status: concept, wacht op controle.</p>",
