   "unit": 2,
   "unit_title_ar": "الوضوء وأحكامه",
   "unit_title_nl": "De woeḍoe en haar regels",
   "title_ar": "فرائض الوضوء ستة",
   "title_nl": "De zes verplichte delen van de woeḍoe",
   "page_start": 34,
   "body_ar": "<p>فرائض الوضوء ستة: غسل الوجه كله ومنه المضمضة والاستنشاق، وغسل اليدين إلى المرفقين، ومسح الرأس كله ومنه الأذنان، والسنة أن يقبل بيديه ويدبر كما في حديث عبد الله بن زيد المتفق عليه، وغسل الرجلين إلى الكعبين وهما العظمان الناتئان أسفل الساق، وفي الحديث: <span class=\"hadith\">ويل للأعقاب من النار</span> ولم يذكر الكتاب مخرجه، والترتيب، والموالاة بألا يؤخر غسل عضو حتى ينشف الذي قبله. ومن قطع عضو منه غسل ما بقي من محل الفرض، والأعضاء الصناعية يمسح عليها إن تعذر نزعها، وتركيبة الأسنان لا يلزم نزعها لحديث عرفجة بن أسعد.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 8، من ص 34. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>Het boek noemt zes farāʾiḍ van de woeḍoe (al-Māʾida 5:6).</p>\n<p>(1) <strong>Het hele gezicht wassen</strong>, met spoelen van de mond en opsnuiven van water, want mond en neus horen bij het gezicht.</p>\n<p>(2) <strong>De handen wassen tot en met de ellebogen.</strong></p>\n<p>(3) <strong>Over het hele hoofd strijken, met de oren.</strong> De soenna is van voren naar achteren en weer terug (al-Bukhārī en Muslim, van ʿAbd Allāh ibn Zayd). Een vrouw strijkt niet over het haar dat afhangt; een kale strijkt van de normale haargrens tot de nek.</p>\n<p>(4) <strong>De voeten wassen tot en met de enkels.</strong> De enkels zijn de uitstekende botjes aan beide kanten onderaan het been, niet de hiel. <span class=\"hadith\">Wee de hielen voor het Vuur</span>; het boek geeft hier geen bron. Let dus op ellebogen, enkels, tussen de tenen en de randen van het gezicht.</p>\n<p>(5) <strong>De volgorde</strong>, zoals Allah de delen noemt en zoals iedereen de woeḍoe van de Profeet ﷺ beschreef.</p>\n<p>(6) <strong>Aaneengesloten wassen</strong>: een deel niet laten drogen voordat je het volgende wast.</p>\n<p><strong>Kwesties.</strong> Bij een geamputeerd deel was je wat van de plicht overblijft, anders vervalt het. Een prothese die makkelijk afgaat, doe je af; anders strijk je erover. Een kunstgebit hoeft er niet uit: ʿArfaja ibn Asʿad kreeg een gouden neus en hoefde die niet af te doen (at-Tirmidhī, ṣaḥīḥ volgens al-Albānī).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Zes verplichte delen: gezicht, handen, hoofd, voeten, volgorde, aaneengesloten.</li>\n<li>Mond en neus horen bij het gezicht.</li>\n<li>De enkels zijn de uitstekende botjes, niet de hiel.</li>\n<li>Een kunstgebit hoeft er voor de woeḍoe niet uit.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 8, vanaf p. 34. Status: concept, wacht op controle.</p>",
