   "title_ar": "نواقض الوضوء",
   "title_nl": "Wat de woeḍoe verbreekt",
   "page_start": 38,
   "body_ar": "<p>نواقض الوضوء: الخارج من السبيلين من بول أو غائط أو ريح أو مني أو مذي أو ودي، لقوله ﷺ: <span class=\"hadith\">لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ</span> متفق عليه؛ وزوال العقل بنوم مستغرق أو سكر أو إغماء أو جنون، لحديث صفوان بن عسال، أما النوم اليسير فلا ينقض لحديث أنس؛ ومس الفرج بلا حائل: <span class=\"hadith\">من مس ذكره فليتوضأ</span>؛ وأكل لحم الإبل: <span class=\"hadith\">نعم، توضأ من لحوم الإبل</span> رواه مسلم. ومن تيقن الطهارة وشك في الحدث فهو على طهارته، والعكس بالعكس، لأن اليقين لا يزول بالشك: <span class=\"hadith\">لا ينصرف حتى يسمع صوتًا أو يجد ريحًا</span> متفق عليه.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 10، من ص 38. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>(1) <strong>Alles wat uit de twee uitgangen komt</strong>: urine, ontlasting, wind, sperma, madhy, wady en andere afscheiding (al-Māʾida 5:6; <span class=\"hadith\">Allah aanvaardt het gebed van niemand van jullie die ḥadath heeft totdat hij woeḍoe doet</span>, al-Bukhārī en Muslim).</p>\n<p>(2) <strong>Het verstand kwijtraken of afdekken</strong>: diepe slaap, dronkenschap, bewusteloosheid of waanzin. Bewijs: de hadith van Ṣafwān ibn ʿAssāl dat sokken niet uit hoeven na ontlasting, urine en slaap (at-Tirmidhī, ḥasan volgens al-Albānī). Lichte slaap verbreekt niet: de metgezellen knikten weg terwijl ze op het ʿishāʾ wachtten en baden zonder woeḍoe (Abū Dāwūd, van Anas). Wat telt is diepe slaap zonder besef, in welke houding ook.</p>\n<p>(3) <strong>Het geslachtsdeel zonder iets ertussen aanraken</strong>: <span class=\"hadith\">Wie zijn geslachtsdeel aanraakt, laat hij woeḍoe doen</span> (van Busra bint Ṣafwān; en van Umm Ḥabība bij Ibn Māja). Dat geldt voor man en vrouw, voor- en achterkant; aanraken van testikels of billen verbreekt niet.</p>\n<p>(4) <strong>Kamelenvlees eten</strong>: <span class=\"hadith\">Ja, doe woeḍoe na kamelenvlees</span> (Muslim, van Jābir ibn Samura); na schapenvlees mag het, hoeft niet.</p>\n<p><strong>Twijfel</strong> (ter kennisname). Wie zeker is van zijn woeḍoe en twijfelt of hij die verbrak, blijft rein; wie zeker is van de ḥadath en twijfelt over woeḍoe, is onrein. Zekerheid wijkt niet voor twijfel: <span class=\"hadith\">Hij gaat niet weg totdat hij een geluid hoort of een geur ruikt</span> (al-Bukhārī en Muslim).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Alles wat uit voor- of achterkant komt, verbreekt de woeḍoe.</li>\n<li>Diepe slaap verbreekt, lichte slaap niet.</li>\n<li>Het geslachtsdeel zonder iets ertussen aanraken verbreekt.</li>\n<li>Kamelenvlees eten verbreekt, schapenvlees niet.</li>\n<li>Bij twijfel ga je uit van wat zeker was.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 10, vanaf p. 38. Status: concept, wacht op controle.</p>",
