   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Door ZAD gemarkeerd als 'المقطع للاطلاع فقط' (alleen ter kennisname): de verschillen tussen verband en sok, medische pleisters en reizen tijdens de termijn (p. 46–47). Over de hadith van Jābir over de man met de hoofdwond (p. 45): volgens mijn controle noemde al-Albānī het deel over verband en strijken zwak. Het boek schrijft de hadith van ʿAmr ibn Umayya over strijken over de tulband toe aan al-Bukhārī en Muslim; ik vond die alleen bij al-Bukhārī. Graag controleren."
