   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Opmerking: de Umm Ḥabība die de ghusl werd opgedragen (p. 49) is Umm Ḥabība bint Jaḥsh, niet de moeder der gelovigen. Het activiteitenblok (p. 53) vraagt naar aaneengesloten wassen bij de ghusl, wat in de tekst niet behandeld wordt."
