   "title_ar": "التيمم",
   "title_nl": "De tayammum: betekenis en wanneer",
   "page_start": 54,
   "body_ar": "<p>التيمم لغة: القصد (البقرة: 267)، وشرعًا: مسح الوجه واليدين بالصعيد الطيب على وجه مخصوص تعبدًا لله، وهو من خصائص هذه الأمة: <span class=\"hadith\">أعطيت خمسًا لم يعطهن نبي قبلي ... وجعلت لي الأرض مسجدًا وطهورًا</span> متفق عليه. ولا يتيمم إلا بعد طلب الماء، لقوله تعالى: ﴿فلم تجدوا ماء﴾. ويشرع عند العجز الحقيقي كعدم الماء، والحكمي كخوف الضرر أو الحاجة إليه للشرب أو شدة البرد: <span class=\"hadith\">إن الصعيد الطيب طهور المسلم وإن لم يجد الماء عشر سنين</span> رواه الترمذي وصححه الألباني. ويكون بتراب طهور له غبار، فإن لم يجد فبما يقدر عليه من رمل أو حجر. وهو يرفع الحدث رفعًا مؤقتًا إلى وجود الماء.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 13، من ص 54. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Betekenis.</strong> Tayammum is in de taal 'je richten op' (al-Baqara 2:267). In de fiqh: gezicht en handen bestrijken met reine aarde, op een vaste manier, als aanbidding. Het is een bijzonderheid van deze gemeenschap: <span class=\"hadith\">Mij zijn vijf dingen gegeven die geen profeet vóór mij kreeg ... de aarde is voor mij een gebedsplaats en een reinigingsmiddel gemaakt</span> (al-Bukhārī en Muslim, van Jābir). Tayammum vervangt woeḍoe en ghusl als die niet kunnen.</p>\n<p><strong>Eerst zoeken.</strong> <span class=\"hadith\">En vinden jullie geen water</span> (an-Nisāʾ 4:43) laat zien dat je eerst moeite doet om water te vinden; 'niet vinden' zeg je pas als je zocht.</p>\n<p><strong>Wanneer.</strong> Bij werkelijk onvermogen: geen water in de woestijn of in een afgesloten ruimte, of water ver weg. Bij onvermogen 'in oordeel': er is water, maar gebruik ervan schaadt je, je hebt het nodig om te drinken, of het is extreem koud. <span class=\"hadith\">Reine aarde is het reinigingsmiddel van de moslim, ook als hij tien jaar geen water vindt</span> (at-Tirmidhī, van Abū Dharr). Tayammum mag ook voor aanbevolen reinheid; de Profeet ﷺ deed het om een groet te beantwoorden (Abū Dāwūd).</p>\n<p><strong>Waarmee.</strong> Met reine aarde met stof als die er is (al-Māʾida 5:6, 'ervan'); anders met zand of steen (at-Taghābun 64:16). Onreine aarde telt niet: <span class=\"hadith\">Haar aarde is voor ons reinigend gemaakt</span> (Muslim, van Ḥudhayfa).</p>\n<p><strong>Tijdelijk.</strong> Volgens het boek heft tayammum de ḥadath tijdelijk op tot er water is. Daarom mag het vóór de gebedstijd en mag je er zoveel gebeden mee doen als je wilt.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Tayammum vervangt woeḍoe en ghusl als water er niet is of niet gebruikt kan worden.</li>\n<li>Zoek eerst naar water.</li>\n<li>Schade, dorst of extreme kou tellen ook als onvermogen.</li>\n<li>Gebruik reine aarde met stof, anders zand of steen.</li>\n<li>Volgens het boek heft tayammum de ḥadath op tot er water is.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 13, vanaf p. 54. Status: concept, wacht op controle.</p>",
