   "title_ar": "فروض التيمم",
   "title_nl": "De verplichte delen en de manier van tayammum",
   "page_start": 56,
   "body_ar": "<p>فروض التيمم: النية، ومسح الوجه، ومسح الكفين، والترتيب. لحديث عمار: <span class=\"hadith\">إنما كان يكفيك أن تقول بيديك هكذا</span> ثم ضرب بيديه الأرض ضربة واحدة ومسح وجهه وكفيه. متفق عليه. وصفته: أن يضرب الأرض بيديه ضربة واحدة مفرجًا أصابعه، ثم يمسح وجهه، ثم ظاهر كفيه براحتيه. ومن خشي خروج الوقت لزمه الوضوء أو الغسل على قول الجمهور، وفاقد الطهورين يصلي على حسب حاله ولا يعيد. وإن وجد الماء قبل الصلاة توضأ، وبعدها لا يعيد، وفي أثنائها بطل تيممه. ويبطل التيمم بمبطلات الوضوء وبوجود الماء مع القدرة على استعماله.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 14، من ص 56. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Vier verplichte delen.</strong> (1) De intentie, een daad van het hart. (2) Over het gezicht strijken. (3) Over de handen strijken, eerst rechts dan links (al-Māʾida 5:6). (4) De volgorde: gezicht vóór handen. Ammār kreeg te horen: <span class=\"hadith\">Het was genoeg geweest als je met je handen zo had gedaan</span>; hij sloeg één keer op de grond en bestreek handen en gezicht (al-Bukhārī en Muslim).</p>\n<p><strong>De manier.</strong> Eén keer met beide handen op de grond slaan, liefst met gespreide vingers; dan het gezicht bestrijken; dan de rug van de handen met de handpalmen.</p>\n<p><strong>Ter kennisname.</strong> Wie bang is dat de gebedstijd voorbij gaat als hij water gebruikt, moet toch woeḍoe of ghusl doen; zelfs wie te laat wakker wordt, moet volgens de meerderheid de ghusl doen. Wie water noch aarde heeft, bidt zoals hij kan en herhaalt niet. Vind je water vóór het gebed, dan woeḍoe; erna, dan herhaal je niet (<span class=\"hadith\">Je hebt de soenna getroffen</span>, Abū Dāwūd); tijdens het gebed, dan vervalt de tayammum en begin je opnieuw met woeḍoe.</p>\n<p><strong>Wat de tayammum verbreekt.</strong> Alles wat de woeḍoe verbreekt, en het vinden van water als je het kunt gebruiken.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Intentie, gezicht, handen en volgorde zijn verplicht.</li>\n<li>Eén slag op de grond is genoeg.</li>\n<li>Water vinden tijdens het gebed verbreekt de tayammum.</li>\n<li>Wie water vond na het gebed, herhaalt het niet.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 14, vanaf p. 56. Status: concept, wacht op controle.</p>",
