   "page_start": 65,
   "body_ar": "<p>من الطاهرات التي حصل فيها خلاف: المؤمن لا ينجس بالموت: <span class=\"hadith\">إن المؤمن لا ينجس</span> متفق عليه؛ وما لا دم له سائل إن تولد من طاهر كالذباب: <span class=\"hadith\">إذا وقع الذباب في شراب أحدكم فليغمسه ثم ليطرحه</span> رواه البخاري؛ وبول ما يؤكل لحمه وروثه ومنيه لحديث العرنيين؛ ومني الآدمي لحديث عائشة؛ ورطوبة فرج المرأة؛ وسؤر الهرة وما يكثر طوافه: <span class=\"hadith\">إنها ليست بنجس إنها من الطوافين عليكم والطوافات</span>. ودم الحيض والنفاس نجس باتفاق، وسائر دم الآدمي طاهر على الراجح، ودم مأكول اللحم طاهر إلا المسفوح، ودم غير المأكول نجس إلا الهرة وما يكثر طوافه، والميتة نجسة إلا السمك والجراد: <span class=\"hadith\">أحلت لنا ميتتان ودمان</span> رواه أحمد وابن ماجه وصححه الألباني.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 16، من ص 65. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>Het boek noemt dingen die volgens hem rein zijn, al verschilden geleerden erover.</p>\n<p>(1) <strong>De gelovige wordt door de dood niet onrein</strong>: <span class=\"hadith\">De gelovige is niet onrein</span> (al-Bukhārī en Muslim).</p>\n<p>(2) <strong>Diertjes zonder stromend bloed</strong>, als ze uit iets reins voortkomen, zoals vliegen en schorpioenen: water waarin ze sterven blijft rein. <span class=\"hadith\">Als een vlieg in de drank van een van jullie valt, laat hij hem onderdompelen en dan wegwerpen</span> (al-Bukhārī). Komen ze uit najāsa voort, zoals kakkerlakken uit het riool, dan zijn ze onrein.</p>\n<p>(3) <strong>Urine, mest en sperma van dieren die je mag eten</strong>: mannen van ʿUkl en ʿUrayna kregen te drinken van melk en urine van kamelen (al-Bukhārī en Muslim), en <span class=\"hadith\">Bid in de schaapskralen</span>. Het boek schrijft dat laatste toe aan Abū Hurayra in al-Bukhārī en Muslim; ik vond het daar niet van hem; graag controleren.</p>\n<p>(4) <strong>Menselijk sperma</strong>: ʿĀʾisha krabde het van zijn kleed en hij bad erin (Muslim).</p>\n<p>(5) <strong>Vocht van de vrouw</strong>: er is niet overgeleverd dat gewassen moest worden.</p>\n<p>(6) <strong>Het restwater van de kat</strong> en dieren die veel in huis rondlopen: <span class=\"hadith\">Ze is niet onrein; ze hoort bij wie bij jullie rondlopen</span> (Abū Dāwūd en at-Tirmidhī, van Abū Qatāda). Ibn ʿUthaymīn: wat veel rondloopt geldt als de kat, behalve de hond.</p>\n<p><strong>Soorten bloed.</strong> Menstruatie- en kraambloed zijn onrein volgens consensus (Asmāʾ: kleding afwrijven en wassen, al-Bukhārī en Muslim). Ander menselijk bloed, uit wonden of tanden, is rein volgens de sterkere mening: de metgezellen baden gewond. Bloed van dieren die je mag eten is rein, behalve stromend bloed (al-Anʿām 6:145); wat na het slachten in vlees, hart, milt en lever blijft is rein. Bloed van dieren die je niet eet is onrein, behalve van kat en huisdieren. Kadaver is onrein volgens consensus, behalve vis en sprinkhaan: <span class=\"hadith\">Ons zijn twee kadavers en twee bloeden toegestaan</span> (Aḥmad en Ibn Māja, ṣaḥīḥ volgens al-Albānī).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Een overleden gelovige is niet onrein.</li>\n<li>Urine en mest van eetbare dieren zijn volgens het boek rein.</li>\n<li>Het restwater van de kat is rein.</li>\n<li>Menstruatiebloed is onrein; bloed uit een wond volgens de sterkere mening niet.</li>\n<li>Dode vis en sprinkhaan zijn rein en toegestaan.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 16, vanaf p. 65. Status: concept, wacht op controle.</p>",
