   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Het boek schrijft «صلوا في مرابض الغنم» toe aan Abū Hurayra in al-Bukhārī en Muslim (p. 65); ik vond het daar niet van hem. Muslim heeft de vraag over schaapskralen van Jābir ibn Samura. Graag controleren."
