   "title_ar": "الحيض والنفاس",
   "title_nl": "Menstruatie",
   "page_start": 69,
   "body_ar": "<p>الحيض لغة السيلان، وشرعًا: دم طبيعة وجبلة يخرج من قعر الرحم في أوقات معلومة حال صحة المرأة من غير ولادة. ولا حيض قبل تسع سنين ولا بعد خمسين غالبًا، وأقله يوم وليلة وأكثره خمسة عشر يومًا عند أكثر الفقهاء وغالبه ست أو سبع، وما دون اليوم والليلة دم فساد نجس ناقض للوضوء. والمبتدأة إذا رأت دمًا بصفات الحيض فهو حيض ما لم يجاوز خمسة عشر يومًا. ويعرف الطهر بانقطاع الدم أو بالقصة البيضاء، لقول عائشة: «لا تعجلن حتى ترين القصة البيضاء» رواه مالك. والكدرة والصفرة المتصلة بالحيض حيض، وبعد الطهر ليست بشيء: «كنا لا نعد الكدرة والصفرة بعد الطهر شيئًا» رواه البخاري. والأرجح أن للحائض قراءة القرآن دون مس المصحف.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 17، من ص 69. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Betekenis.</strong> Ḥayḍ is in de taal 'stromen'. In de fiqh: natuurlijk bloed uit de diepte van de baarmoeder op bekende tijden, bij een gezonde vrouw, niet door een bevalling.</p>\n<p><strong>Leeftijd en duur.</strong> Geen menstruatie vóór negen jaar, en meestal niet na vijftig. Minimaal een dag en nacht, maximaal vijftien dagen volgens de meeste fuqahāʾ; wat langer duurt is istiḥāḍa. Meestal zes of zeven dagen. Bloed korter dan een dag en nacht is volgens het boek 'bedorven bloed' (dam fasād): geen regels van menstruatie, maar wel onrein en het verbreekt de woeḍoe.</p>\n<p><strong>Het eerste bloed.</strong> Een meisje dat voor het eerst bloedt: heeft het de kenmerken van menstruatie, dan is het menstruatie, tot vijftien dagen; daarna istiḥāḍa (al-Baqara 2:222).</p>\n<p><strong>Wanneer is ze rein?</strong> (1) Het bloed stopt: een doekje komt schoon terug, zonder bruin of geel. (2) Ze ziet de witte afscheiding (al-qaṣṣa al-bayḍāʾ): ʿĀʾisha zei tegen vrouwen: <span class=\"hadith\">Haast je niet tot je de witte afscheiding ziet</span> (Mālik, ṣaḥīḥ volgens al-Albānī). Dit is een uitspraak van ʿĀʾisha, niet van de Profeet ﷺ.</p>\n<p><strong>Bruin en geel.</strong> Vast aan de menstruatie (ervoor, erna of ertussen) is het menstruatie; los ervan niet: <span class=\"hadith\">We rekenden bruin en geel na de reinheid nergens toe</span> (al-Bukhārī, Umm ʿAṭiyya).</p>\n<p><strong>Koran reciteren.</strong> Volgens het boek mag een menstruerende vrouw de Koran reciteren, vooral als ze het nodig heeft (studente, lerares), zonder de muṣḥaf aan te raken.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Menstruatie duurt minimaal een dag en nacht en maximaal vijftien dagen.</li>\n<li>Reinheid herken je aan het stoppen van het bloed of de witte afscheiding.</li>\n<li>Bruin en geel tellen alleen mee als ze aan de menstruatie vastzitten.</li>\n<li>Volgens het boek mag een menstruerende vrouw Koran reciteren zonder de muṣḥaf aan te raken.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 17, vanaf p. 69. Status: concept, wacht op controle.</p>",
