   "title_nl": "Kraambloed",
   "page_start": 74,
   "body_ar": "<p>المستحاضة لها حكم الطاهرات في كل شيء إلا وجوب الوضوء لكل صلاة بعد دخول وقتها. والنفاس هو الدم الخارج من الرحم بسبب الولادة، وهو بقية الدم المحتبس في مدة الحمل، ولا حد لأقله، وأكثره أربعون يومًا، فما زاد فاستحاضة. والنفاس كالحيض فيما يحل وفيما يحرم وفي وجوب الغسل عند انقطاعه، وتقضي النفساء الصيام دون الصلاة، وإذا انقطع دمها قبل الأربعين اغتسلت وصلت. وإن ألقت الحامل ما تبين فيه خلق إنسان فلها أحكام النفساء، وأقل ذلك واحد وثمانون يومًا وغالبه ثلاثة أشهر، وإن ألقت علقة أو مضغة لم يتبين فيها تخطيط فليس بنفاس. والنساء أربعة أضرب: طاهر وحائض ومستحاضة وذات دم فساد.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 19، من ص 74. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>Ter kennisname begint het boek met de vrouw met istiḥāḍa: in alles geldt zij als reine vrouw (vasten, bidden, ṭawāf, reciteren, de muṣḥaf aanraken, gemeenschap), behalve dat zij voor elk gebed woeḍoe doet na het begin van de tijd.</p>\n<p><strong>Nifās</strong> is het bloed dat door de bevalling uit de baarmoeder komt: het restant van het bloed dat tijdens de zwangerschap werd vastgehouden. Het lijkt meestal op menstruatiebloed.</p>\n<p><strong>Duur.</strong> Er is geen minimum; het kan maar een paar dagen duren. Het maximum is veertig dagen; wat langer duurt is istiḥāḍa.</p>\n<p><strong>Regels.</strong> Kraambloed is als menstruatie in wat mag (genieten van elkaar behalve gemeenschap) en wat verboden is (gemeenschap, vasten, bidden, echtscheiding, ṭawāf, verblijf in de moskee), en in de plicht van de ghusl als het stopt. Ze haalt het vasten in, niet het gebed. Stopt het vóór veertig dagen, dan is haar kraamtijd voorbij: ze wast zich en bidt.</p>\n<p><strong>Miskraam</strong> (ter kennisname). Als er al iets menselijks te zien was, gelden de regels van kraambloed; dat is meestal na drie maanden, op zijn vroegst na 81 dagen. Bij een klompje bloed of vlees zonder menselijke vorm is het geen kraambloed: ze blijft bidden en vasten.</p>\n<p><strong>Vier soorten vrouwen</strong> (ter kennisname): rein; menstruerend (bloed in de tijd van de menstruatie); met istiḥāḍa (bloed in aansluiting op de menstruatie dat geen menstruatie is); met bedorven bloed (bloed buiten de tijd en niet aansluitend). Bedorven bloed verhindert gebed en vasten niet, maar is onrein en verbreekt de woeḍoe.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Kraambloed heeft geen minimum en maximaal veertig dagen.</li>\n<li>Voor kraambloed gelden dezelfde regels als voor menstruatie.</li>\n<li>Stopt het eerder, dan wast ze zich en bidt ze.</li>\n<li>Een miskraam zonder menselijke vorm geeft geen kraambloed.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 19, vanaf p. 74. Status: concept, wacht op controle.</p>",
