   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Door ZAD gemarkeerd als 'المقطع للاطلاع فقط' (alleen ter kennisname): de regel dat de vrouw met istiḥāḍa als rein geldt, de bladzijde over kraambloed, de miskraam en de vier soorten vrouwen (p. 74–75)."
