   "title_nl": "Het gebed: betekenis, plaats en verdienste",
   "page_start": 81,
   "body_ar": "<p>الصلاة لغة الدعاء (التوبة: 103)، وشرعًا: التعبد لله بأقوال وأفعال مخصوصة مفتتحة بالتكبير مختتمة بالتسليم. وهي الركن الثاني من أركان الإسلام: <span class=\"hadith\">بني الإسلام على خمس</span> متفق عليه. ومن فضلها: <span class=\"hadith\">الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان مكفرات ما بينهن إذا اجتنب الكبائر</span> رواه مسلم، و<span class=\"hadith\">فذلك مثل الصلوات الخمس يمحو الله بهن الخطايا</span> متفق عليه. وفرضت ليلة الإسراء والمعراج قبل الهجرة، في السماء، بلا واسطة، خمسين صلاة. والحكمة منها شكر النعم وإظهار العبودية والصلة بين العبد وربه.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 20، من ص 81. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Betekenis.</strong> Ṣalāt is in de taal smeekbede: <span class=\"hadith\">En bid voor hen</span> (at-Tawba 9:103). In de fiqh: aanbidding van Allah met vaste woorden en handelingen, begonnen met de takbīr en afgesloten met de taslīm.</p>\n<p><strong>Plaats.</strong> Het gebed is de tweede zuil van de islam na de getuigenis: <span class=\"hadith\">De islam is gebouwd op vijf</span> (al-Bukhārī en Muslim).</p>\n<p><strong>Verdienste.</strong> <span class=\"hadith\">De vijf gebeden, van vrijdag tot vrijdag en van Ramadan tot Ramadan, wissen uit wat ertussen ligt, zolang de grote zonden vermeden worden</span> (Muslim, van Abū Hurayra). <span class=\"hadith\">Als er een rivier voor jullie deur liep waarin je je vijf keer per dag wast, zou er dan vuil achterblijven? Zo is het met de vijf gebeden: Allah wist er de zonden mee uit</span> (al-Bukhārī en Muslim).</p>\n<p><strong>Ter kennisname.</strong> Het gebed is bijzonder omdat het tot de Nachtreis en Hemelvaart werd uitgesteld, zonder tussenpersoon werd opgelegd, in de hemel werd opgelegd en eerst vijftig gebeden waren. Het werd opgelegd in de nacht van de Isrāʾ en Miʿrāj, vóór de hijra. De wijsheid: dankbaarheid voor Allah's gunsten, en het duidelijkste teken van aanbidding: je wendt je tot Allah, vernedert je voor Hem en spreekt Hem toe in recitatie, gedenken en smeekbede.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Het gebed begint met de takbīr en eindigt met de taslīm.</li>\n<li>Het is de tweede zuil van de islam.</li>\n<li>De vijf gebeden wissen kleine zonden uit, zolang grote zonden vermeden worden.</li>\n<li>Het werd opgelegd in de nacht van de Isrāʾ en Miʿrāj, vóór de hijra.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 20, vanaf p. 81. Status: concept, wacht op controle.</p>",
