   "title_ar": "شروط صحة الأذان",
   "title_nl": "Voorwaarden van de adhān",
   "page_start": 87,
   "body_ar": "<p>شروط صحة الأذان: دخول الوقت إلا الأذان الأول للفجر والجمعة، والترتيب والموالاة بين ألفاظه، وأن يكون بالعربية وبالألفاظ الواردة. ولا يشترط له طهارة ولا استقبال ولا قيام، ويستحب ذلك كله. ويشترط في المؤذن أن يكون مسلمًا عاقلًا ذكرًا. ويستحب أن يكون عدلًا أمينًا، بالغًا، عالمًا بالأوقات، حسن الصوت، متطهرًا، قائمًا مستقبل القبلة، يتمهل في الأذان ويسرع في الإقامة. والالتفات يمينًا وشمالًا في الحيعلتين سنة لحديث أبي جحيفة في أذان بلال، ولا يلتفت من أذن بمكبر الصوت.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 23، من ص 87. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Voorwaarden voor een geldige adhān.</strong> (1) De tijd is begonnen; uitzonderingen zijn de eerste adhān voor het fajr-gebed en de eerste adhān voor het vrijdaggebed. (2) De volgorde en aaneengesloten zinnen, zoals de soenna ze geeft. (3) In het Arabisch en met de overgeleverde woorden.</p>\n<p>Reinheid, richting Qibla, staan en niet praten zijn geen voorwaarde, maar wel aanbevolen. Een korte pauze tussen de zinnen is soenna; iets langer is geen probleem.</p>\n<p><strong>De muʾadhdhin</strong> moet moslim, verstandig en man zijn. De adhān van een ongelovige, waanzinnige, dronkene of kind zonder onderscheidingsvermogen is niet geldig, en een vrouw roept niet voor mannen.</p>\n<p><strong>Aanbevolen eigenschappen</strong> (ter kennisname): betrouwbaar (mensen gaan op hem af voor gebed en vasten), volwassen (al is de adhān van een kind met onderscheidingsvermogen geldig), kennis van de tijden, een mooie stem, rein van beide ḥadath, staand naar de Qibla, langzaam bij de adhān en snel bij de iqāma.</p>\n<p><strong>Hoofd draaien.</strong> Rechts en links draaien bij ḥayya ʿalā ṣ-ṣalāh en ḥayya ʿalā l-falāḥ is soenna (al-Bukhārī en Muslim, van Abū Juḥayfa over Bilāl). Wie met een microfoon roept, draait volgens het boek niet, want de luidsprekers doen het werk.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>De adhān is pas geldig als de tijd begonnen is, op twee uitzonderingen na.</li>\n<li>Volgorde, aaneengesloten zinnen en Arabisch zijn voorwaarden.</li>\n<li>De muʾadhdhin is moslim, verstandig en man.</li>\n<li>Langzaam bij de adhān, snel bij de iqāma.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 23, vanaf p. 87. Status: concept, wacht op controle.</p>",
