   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Door ZAD gemarkeerd als 'المقطع للاطلاع فقط' (alleen ter kennisname): de vernieuwingen bij de adhān (p. 89) en de fouten en kwesties (p. 91). Het boek citeert de adhān van Abū Maḥdhūra (Abū Dāwūd en Ibn Māja) zonder de herhaling van de getuigenis (tarjīʿ) die in die overlevering staat. Graag controleren."
