   "title_nl": "De gebedstijden: ẓuhr en ʿaṣr",
   "page_start": 95,
   "body_ar": "<p>الصلوات المفروضة خمس، لكل صلاة منها وقت محدد (النساء: 103)، والأصل فيها حديث عبد الله بن عمرو: <span class=\"hadith\">وقت الظهر إذا زالت الشمس ... ووقت صلاة الصبح من طلوع الفجر ما لم تطلع الشمس</span> رواه مسلم. ووقت الظهر من الزوال إلى أن يصير ظل كل شيء مثله، ويستحب تعجيلها إلا في شدة الحر: <span class=\"hadith\">إذا اشتد الحر فأبردوا بالصلاة فإن شدة الحر من فيح جهنم</span> متفق عليه. ووقت العصر من نهاية وقت الظهر إلى غروب الشمس، ويسن تعجيلها، وهي الصلاة الوسطى (البقرة: 238). <span class=\"hadith\">من فاتته صلاة العصر فكأنما وتر أهله وماله</span> متفق عليه، <span class=\"hadith\">من ترك صلاة العصر فقد حبط عمله</span> رواه البخاري.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 25، من ص 95. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>Elk van de vijf gebeden heeft een vaste tijd die de sharia bepaalt: <span class=\"hadith\">Het gebed is voor de gelovigen een voorschrift op vastgestelde tijden</span> (an-Nisāʾ 4:103). De basis is de hadith van ʿAbd Allāh ibn ʿAmr: <span class=\"hadith\">De tijd van ẓuhr is als de zon over het hoogste punt is ... tot ʿaṣr komt; de tijd van ʿaṣr zolang de zon niet geel wordt; de tijd van maghrib zolang de schemering niet weg is; de tijd van ʿishāʾ tot de helft van de nacht; de tijd van fajr vanaf de dageraad zolang de zon niet opkomt</span> (Muslim).</p>\n<p><strong>Ẓuhr</strong> begint als de zon over het hoogste punt naar het westen zakt, en loopt tot de schaduw van iets even lang is als het ding zelf. Het is aanbevolen ẓuhr vroeg te bidden, behalve bij grote hitte: <span class=\"hadith\">Als de hitte hevig is, stel het gebed uit tot het koeler is, want hevige hitte komt van de adem van de Hel</span> (al-Bukhārī en Muslim).</p>\n<p><strong>ʿAṣr</strong> begint waar ẓuhr eindigt; het is soenna het vroeg te bidden, en de tijd loopt tot de zon helemaal onder is. Het is het middelste gebed (al-Baqara 2:238).</p>\n<p><strong>Waarschuwing.</strong> <span class=\"hadith\">Wie het ʿaṣr-gebed mist, is als wie zijn gezin en bezit verloor</span> (al-Bukhārī en Muslim) en <span class=\"hadith\">Wie het ʿaṣr-gebed laat, diens werk is tenietgedaan</span> (al-Bukhārī).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Elk gebed heeft een vaste tijd.</li>\n<li>Ẓuhr: van het zakken van de zon tot de schaduw even lang is als het ding.</li>\n<li>Bij grote hitte stel je ẓuhr uit tot het koeler is.</li>\n<li>ʿAṣr is het middelste gebed; wie het laat, verliest zijn werk.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 25, vanaf p. 95. Status: concept, wacht op controle.</p>",
