   "title_ar": "وقت المغرب",
   "title_nl": "De tijden van maghrib, ʿishāʾ en fajr",
   "page_start": 96,
   "body_ar": "<p>وقت المغرب من تكامل غروب الشمس إلى مغيب الشفق الأحمر: <span class=\"hadith\">وقت صلاة المغرب ما لم يغب الشفق</span> رواه مسلم، ويسن تعجيلها: <span class=\"hadith\">لا تزال أمتي بخير ما لم يؤخروا المغرب حتى تشتبك النجوم</span> رواه أبو داود وصححه الألباني. ووقت العشاء من مغيب الشفق إلى نصف الليل: <span class=\"hadith\">ووقت صلاة العشاء إلى نصف الليل الأوسط</span> رواه مسلم، ونصف الليل منتصف ما بين المغرب والفجر لا الساعة الثانية عشرة، والصلاة بعده قضاء. ووقت الفجر من طلوع الفجر الصادق إلى طلوع الشمس، والسنة التعجيل لحديث عائشة في المتلفعات بمروطهن، ولا يجوز تأخيرها عمدًا حتى تطلع الشمس.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 26، من ص 96. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p><strong>Maghrib</strong> begint als de zon helemaal onder is en loopt tot de rode schemering verdwijnt: <span class=\"hadith\">De tijd van maghrib is zolang de schemering niet weg is</span> (Muslim). De schemering (shafaq) is de roodheid na zonsondergang. Het is soenna maghrib vroeg te bidden: <span class=\"hadith\">Mijn gemeenschap blijft in het goede zolang zij maghrib niet uitstellen tot de sterren talrijk zijn</span> (Abū Dāwūd, ṣaḥīḥ volgens al-Albānī).</p>\n<p><strong>ʿIshāʾ</strong> begint als de rode schemering weg is en eindigt na de eerste helft van de nacht: <span class=\"hadith\">De tijd van ʿishāʾ is tot de helft van de nacht</span> (Muslim). Let op: dat is het midden tussen maghrib en fajr, niet middernacht van de klok zoals veel mensen denken. Wie later bidt, haalt in.</p>\n<p><strong>Fajr</strong> loopt van de ware dageraad tot zonsopgang. De soenna is het vroeg te bidden: gelovige vrouwen baden mee in hun omslagdoeken en gingen naar huis terwijl niemand hen herkende door het donker (al-Bukhārī en Muslim, van ʿĀʾisha). Fajr mag je niet opzettelijk uitstellen tot na zonsopgang; volgens het boek is het gebed dan ongeldig en buiten de tijd.</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Maghrib loopt tot de rode schemering weg is; bid het vroeg.</li>\n<li>ʿIshāʾ loopt tot de helft van de nacht tussen maghrib en fajr.</li>\n<li>De helft van de nacht is niet middernacht van de klok.</li>\n<li>Fajr loopt tot zonsopgang; bid het vroeg in het donker.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 26, vanaf p. 96. Status: concept, wacht op controle.</p>",
