   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Het boek noemt een fajr-gebed dat opzettelijk na zonsopgang wordt gebeden 'ongeldig en buiten de tijd' (p. 97); dat is de formulering van het boek."
