   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Door ZAD gemarkeerd als 'المقطع للاطلاع فقط' (alleen ter kennisname): bidden in vliegtuig, auto en boot, afbeeldingen op kleding en het dragen van urinepotjes of een katheter (p. 101–102). De toevoeging 'en kun je dat niet, dan op je rug' wordt aan an-Nasāʾī toegeschreven; in de gangbare uitgave van zijn Sunan vond ik die niet. Graag controleren."
