   "title_nl": "De zuilen van het gebed (1): staan, takbīr en al-Fātiḥa",
   "page_start": 103,
   "body_ar": "<p>من أركان الصلاة: القيام في الفريضة على القادر (البقرة: 238): <span class=\"hadith\">صل قائمًا فإن لم تستطع فقاعدًا فإن لم تستطع فعلى جنب</span> رواه البخاري، فإن قدر على القيام وعجز عن الركوع أو السجود سقط ما عجز عنه فقط، وأما النافلة فتجوز قاعدًا والقيام أفضل: <span class=\"hadith\">صلاة الرجل قاعدًا على نصف الصلاة</span> رواه مسلم. وتكبيرة الإحرام، ولا يجزئ غير «الله أكبر»: <span class=\"hadith\">إذا قمت إلى الصلاة فكبر</span> متفق عليه، <span class=\"hadith\">تحريمها التكبير وتحليلها التسليم</span>. وقراءة الفاتحة في كل ركعة قراءة صحيحة مرتبة متوالية، ويستثنى المسبوق إذا أدرك الإمام راكعًا، وتجب على كل مصل: <span class=\"hadith\">لا صلاة لمن لم يقرأ بفاتحة الكتاب</span> متفق عليه.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 28، من ص 103. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>De zuilen (arkān) zijn de onmisbare delen van het gebed. Het boek noemt er twaalf; deze les behandelt de eerste drie.</p>\n<p>(1) <strong>Staan</strong> in het verplichte gebed, voor wie het kan (al-Baqara 2:238): <span class=\"hadith\">Bid staand; kun je dat niet, dan zittend; en kun je dat niet, dan op je zij</span> (al-Bukhārī). Wie niet kan staan, bidt naar vermogen. Wie wel kan staan maar niet kan buigen of neerknielen, laat alleen dat weg; je laat alleen vallen wat je niet kunt. Een vrijwillig gebed mag zittend, al is staan beter: <span class=\"hadith\">Het gebed van een man die zit is de helft van het gebed</span> (Muslim).</p>\n<p>(2) <strong>De openingstakbīr</strong>: alleen 'Allāhu akbar' telt, en zonder deze takbīr begint het gebed niet: <span class=\"hadith\">Als je opstaat voor het gebed, zeg dan Allāhu akbar</span> (al-Bukhārī en Muslim, tegen de man die slecht bad) en <span class=\"hadith\">De ingang is de takbīr en de uitgang de taslīm</span> (Abū Dāwūd).</p>\n<p>(3) <strong>Al-Fātiḥa in elke rakʿa</strong>, volledig, correct, in volgorde en aaneengesloten. Uitzondering is wie later aansluit en de imam in de rukūʿ vindt, of te weinig tijd heeft om haar te lezen. Ze is verplicht voor iedereen, imam, volger en alleen biddende, hardop of stil: <span class=\"hadith\">Geen gebed voor wie al-Fātiḥa niet leest</span> (al-Bukhārī en Muslim).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Staan is een zuil in het verplichte gebed voor wie het kan.</li>\n<li>Je laat alleen weg wat je echt niet kunt.</li>\n<li>Het gebed begint alleen met 'Allāhu akbar'.</li>\n<li>Al-Fātiḥa is in elke rakʿa verplicht, ook voor wie achter de imam bidt.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 28, vanaf p. 103. Status: concept, wacht op controle.</p>",
