   "title_nl": "De soenna's van het gebed (1)",
   "page_start": 109,
   "body_ar": "<p>من سنن الصلاة: رفع اليدين في أربعة مواضع: مع تكبيرة الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول، لحديث ابن عمر وأبي حميد، مع مد الأصابع؛ ووضع اليمنى على الشمال حال القيام لحديث سهل بن سعد ووائل بن حجر، وله وضعهما على صدره أو فوق السرة أو تحتها؛ ودعاء الاستفتاح والأفضل التنويع بين الوارد؛ والتعوذ (النحل: 98)؛ والبسملة سرًا، ولا يسن الجهر بها، قال الترمذي: «وعليه العمل عند أكثر أهل العلم من أصحاب النبي ﷺ»؛ والتأمين: <span class=\"hadith\">إذا أمن الإمام فأمنوا فإن الملائكة تؤمن فمن وافق تأمينه تأمين الملائكة غفر له ما تقدم من ذنبه</span> رواه البخاري.</p>\n<p class=\"source\">المصدر: كتاب الفقه (١)، المحاضرة 31، من ص 109. ملخص بصياغة المحرِّر، بانتظار المراجعة.</p>",
   "body_nl": "<p>(1) <strong>De handen heffen</strong> op vier momenten: bij de openingstakbīr, bij de rukūʿ, bij het opkomen eruit, en bij het opstaan na de eerste tashahhud (al-Bukhārī en Muslim, van Ibn ʿUmar; Abū Dāwūd, van Abū Ḥumayd). De vingers gestrekt en niet gespreid (Abū Dāwūd, van Abū Hurayra).</p>\n<p>(2) <strong>Rechts op links leggen</strong> bij het staan: <span class=\"hadith\">De mensen werd opgedragen de rechterhand op de linkeronderarm te leggen</span> (Sahl ibn Saʿd; het boek zegt 'in beide Ṣaḥīḥ's', ik vond het alleen bij al-Bukhārī; graag controleren) en Wāʾil ibn Ḥujr: op de hand, de pols en de onderarm (Abū Dāwūd). Op de borst, boven of onder de navel: volgens het boek is daar ruimte, want over de plaats is geen authentieke hadith.</p>\n<p>(3) <strong>De openingssmeekbede</strong>, het liefst afwisselend: 'Allāhumma bāʿid baynī wa bayna khaṭāyāya ...' (al-Bukhārī en Muslim), 'Subḥānaka llāhumma wa bi-ḥamdik ...' (Abū Dāwūd), 'Allāhu akbar kabīran ...' (Muslim).</p>\n<p>(4) <strong>Toevlucht zoeken</strong> vóór de recitatie (an-Naḥl 16:98).</p>\n<p>(5) <strong>De basmala</strong> stil vóór al-Fātiḥa en vóór de sūra erna. Hardop is volgens het boek geen soenna; at-Tirmidhī zei dat de meeste geleerden onder de metgezellen zo deden.</p>\n<p>(6) <strong>Āmīn</strong> na al-Fātiḥa, voor iedereen; in hardop gereciteerde gebeden zeggen imam en volger het hardop: <span class=\"hadith\">Als de imam āmīn zegt, zeg dan āmīn, want de engelen zeggen āmīn; wiens āmīn samenvalt met die van de engelen, diens eerdere zonden worden vergeven</span> (al-Bukhārī).</p>\n<h3>Kernpunten</h3>\n<ul>\n<li>Handen heffen op vier momenten.</li>\n<li>Rechts op links; de plaats op de borst of buik is volgens het boek ruim.</li>\n<li>Wissel de openingssmeekbeden af.</li>\n<li>De basmala zeg je stil.</li>\n<li>Āmīn zeg je hardop in hardop gereciteerde gebeden.</li>\n</ul>\n<p class=\"source\">Bron: الفقه (١), les 31, vanaf p. 109. Status: concept, wacht op controle.</p>",
