   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Het boek schrijft de hadith van Sahl ibn Saʿd over rechts op links toe aan beide Ṣaḥīḥ's (p. 109); ik vond hem alleen bij al-Bukhārī. Graag controleren."
