   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Het boek noemt de overlevering van Anas over ʿUmar ibn ʿAbd al-ʿAzīz ḥasan volgens al-Albānī (p. 112); volgens mijn controle noemde al-Albānī haar zwak. Bij het verbod op naar de hemel kijken is de eerste bewoording van Muslim; al-Bukhārī heeft 'of hun zicht wordt hun ontnomen'. Graag controleren."
