   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Door ZAD gemarkeerd als 'المقطع للاطلاع فقط' (alleen ter kennisname): de drie vormen van rondkijken (p. 121). Het boek schrijft het verbod op het bedekken van de mond toe aan Abū Dāwūd en at-Tirmidhī (p. 122); ik vond het bij Abū Dāwūd en Ibn Māja. Graag controleren."
