   "opmerking": "Concept. Verzen alleen met vindplaats; Nederlandse weergave is strekking. Hadith gemarkeerd met span.hadith. Groepsoordelen weergegeven als 'volgens het boek'. Geen door ZAD bevestigde toetsstof. Door ZAD gemarkeerd als 'المقطع للاطلاع فقط' (alleen ter kennisname): de vijf soorten beweging in het gebed (p. 123)."
